const r = await tools.exec_command({
  cmd: "git status --short --branch && git log -6 --oneline && git rev-parse HEAD && git rev-parse origin/main && make source-integrity",
  workdir: "/Users/arthur/Documents/Arthur/lion-data-engineer-takehome",
  yield_time_ms: 30000,
  max_output_tokens: 20000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "rg --files -g 'AGENTS.md' -g 'SPEC.md' -g 'README.md' -g 'docs/**' -g 'src/**' -g 'sql/**' -g 'tests/**' -g 'output/**' -g 'LionDEExam/**' | sort && find AGENTS.md SPEC.md README.md docs src sql tests output LionDEExam -type f -maxdepth 8 -print0 2>/dev/null | xargs -0 wc -c | sort -n",
  workdir: "/Users/arthur/Documents/Arthur/lion-data-engineer-takehome",
  yield_time_ms: 30000,
  max_output_tokens: 30000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "cat AGENTS.md SPEC.md README.md LionDEExam/candidate_package/README.md docs/ai/session_index.md",
  workdir: "/Users/arthur/Documents/Arthur/lion-data-engineer-takehome",
  yield_time_ms: 30000,
  max_output_tokens: 40000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "nl -ba SPEC.md | sed -n '1,260p'; nl -ba SPEC.md | sed -n '261,520p'",
  workdir: "/Users/arthur/Documents/Arthur/lion-data-engineer-takehome",
  yield_time_ms: 30000,
  max_output_tokens: 40000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "textutil -convert txt -stdout 'LionDEExam/01_考題卷_資料工程師TakeHome.docx'",
  workdir: "/Users/arthur/Documents/Arthur/lion-data-engineer-takehome",
  yield_time_ms: 30000,
  max_output_tokens: 30000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "cat docs/part_a_model_design.md docs/part_a_quality_report.md docs/part_a_rerun_evidence.md docs/source_inventory.md docs/ai/collaboration_report.md",
  workdir: "/Users/arthur/Documents/Arthur/lion-data-engineer-takehome",
  yield_time_ms: 30000,
  max_output_tokens: 50000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "cat docs/part_a_quality_report.md; cat docs/part_a_model_design.md",
  workdir: "/Users/arthur/Documents/Arthur/lion-data-engineer-takehome",
  yield_time_ms: 30000,
  max_output_tokens: 50000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "for f in docs/evidence/phase_02/*.json docs/evidence/phase_03/*.json; do echo \"$f\"; cat \"$f\"; done",
  workdir: "/Users/arthur/Documents/Arthur/lion-data-engineer-takehome",
  yield_time_ms: 30000,
  max_output_tokens: 50000
});
text(r.output);

